import React, { useEffect, useState } from "react";
import axios from "axios";
import VideoCarousel from "./VideoCarousel";
import ActivityCarousel from "./ActivityCarousel";
import TestimonialGrid from "./TestimonialGrid";

export default function Home() {
  const [data, setData] = useState(null);

  useEffect(() => {
    axios.get("http://localhost:5000/api/home")
      .then(res => setData(res.data))
      .catch(err => console.error(err));
  }, []);

  if (!data) return <p>Loading...</p>;

  return (
    <main className="container home-page">
      <VideoCarousel videoList={data.bannerVideos || []} />

      <section className="two-col card">
        <div className="left-col">
          <h2 style={{ color: "#0b3a73" }}>Welcome</h2>
          <p>{data.welcomeText}</p>
        </div>

        <div className="right-col activities">
          <h3>Activities</h3>
          <ActivityCarousel images={data.activities || []} />
        </div>
      </section>

      <TestimonialGrid videos={data.testimonialVideos || []} />
    </main>
  );
}
